@startuml

class Airline {
  + Name : string
}

class Airplane {
  + Name : string
  + Type : string
  + YearOfManufacture : int
  + NextInspectionDate : date
}

class PassengerPlane extends Airplane {
  + NumberOfSeats : int
}

class SeatCategory {
  + Designation : string
  + OffersEntertainment : boolean
  + SeatCount : int
}

class Flight {
  + FlightNumber : string
  + Date : date
}

class Passenger {
  + Name : string
  + PassportNumber : string
}

class Ticket {
  + TicketNumber : string
  + Price : float
  + UpgradeDesired : boolean
}

class FlightAttendant {
  + Name : string
  + DateOfEmployment : date
  + IsChiefStewardess : boolean
}

class Pilot {
  + Name : string
  + DateOfEmployment : date
  + License : string
}

class Airport {
  + Name : string
  + Address : string
  + RunwayCount : int
}

Airline "1" -- "0..*" Airplane
PassengerPlane "1" *-- "1..*" SeatCategory
Airplane "0..*" -- "0..1" Airline : belongs to
Airplane "0..*" -- "0..1" Airport : home airport
Flight "0..*" -- "1" Airplane
Flight "0..*" -- "1" Airport : departure airport
Flight "0..*" -- "1" Airport : destination airport
Flight "1" -- "0..*" Ticket
Passenger "1" -- "0..*" Ticket
SeatCategory "1" -- "0..*" Ticket
Flight "1" -- "0..*" FlightAttendant
Flight "1" -- "1 Captain" Pilot
Flight "1" -- "1..2 Co-pilot" Pilot
Passenger "1..*" -- "0..*" Flight

@enduml

